1	import React, { useCallback, useEffect, useRef, useState } from 'react';
2	import { apiFetch } from '../../lib/runtime';
3	
4	interface TermLine { id: number; text: string; type: 'cmd' | 'out' | 'err' | 'info'; }
5	
6	const CHEATSHEET = [
7	    {
8	        category: 'Oracle',
9	        commands: [
10	            { cmd: 'oracle <prompt>',       desc: 'Send prompt to Oracle (streaming)' },
11	            { cmd: 'oracle --council <q>',  desc: 'Aeonic Council deliberation' },
12	            { cmd: 'oracle status',         desc: 'System health + model status' },
13	        ]
14	    },
15	    {
16	        category: 'Offload',
17	        commands: [
18	            { cmd: 'offload deepseek <task>', desc: 'Route to local Deepseek' },
19	            { cmd: 'offload qwen <task>',     desc: 'Route to local Qwen' },
20	            { cmd: 'offload kimi <task>',     desc: 'Route to cloud Kimi' },
21	            { cmd: 'offload --swarm <task>',  desc: 'Fan-out via Ruflo swarm' },
22	        ]
23	    },
24	    {
25	        category: 'GitNexus',
26	        commands: [
27	            { cmd: 'gitnexus impact <sym>',   desc: 'Blast radius analysis' },
28	            { cmd: 'gitnexus context <sym>',  desc: 'Full symbol context' },
29	            { cmd: 'gitnexus query <concept>',desc: 'Semantic code search' },
30	        ]
31	    },
32	    {
33	        category: 'System',
34	        commands: [
35	            { cmd: 'tokens',        desc: 'Show session + weekly token spend' },
36	            { cmd: 'pm2 status',    desc: 'Backend process status' },
37	            { cmd: 'pm2 restart all', desc: 'Restart all PM2 processes' },
38	            { cmd: 'ls .claude/state/', desc: 'Show state files' },
39	        ]
40	    }
41	];
42	
43	let lineId = 0;
44	
45	export default function OracleTerminal() {
46	    const [lines, setLines]     = useState<TermLine[]>([
47	        { id: lineId++, text: 'NUDIMMUD terminal — type "help" for cheatsheet', type: 'info' },
48	        { id: lineId++, text: `WS bridge: ${window.location.protocol === 'https:' ? 'wss' : 'ws'}://${window.location.host}/ws/shell`, type: 'info' },
49	    ]);
50	    const [input, setInput]     = useState('');
51	    const [history, setHistory] = useState<string[]>([]);
52	    const [histIdx, setHistIdx] = useState(-1);
53	    const [showSheet, setShowSheet] = useState(true);
54	    const bottomRef = useRef<HTMLDivElement>(null);
55	    const wsRef     = useRef<WebSocket | null>(null);
56	
57	    // Connect WebSocket shell
58	    useEffect(() => {
59	        try {
60	            const proto = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
61	            const ws = new WebSocket(`${proto}//${window.location.host}/ws/shell`);
62	            ws.onmessage = (e) => {
63	                try {
64	                    const { type, data } = JSON.parse(e.data);
65	                    setLines(prev => [...prev, { id: lineId++, text: String(data || ''), type: type === 'stderr' ? 'err' : 'out' }]);
66	                } catch {
67	                    setLines(prev => [...prev, { id: lineId++, text: String(e.data), type: 'out' }]);
68	                }
69	            };
70	            ws.onerror = () => setLines(prev => [...prev, { id: lineId++, text: 'WS: connection failed — shell integration unavailable', type: 'err' }]);
71	            wsRef.current = ws;
72	            return () => ws.close();
73	        } catch {
74	            setLines(prev => [...prev, { id: lineId++, text: 'WS: not available', type: 'info' }]);
75	        }
76	    }, []);
77	
78	    useEffect(() => { bottomRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [lines]);
79	
80	    const submit = useCallback(() => {
81	        const cmd = input.trim();
82	        if (!cmd) return;
83	        setLines(prev => [...prev, { id: lineId++, text: `$ ${cmd}`, type: 'cmd' }]);
84	        setHistory(prev => [cmd, ...prev.slice(0, 49)]);
85	        setHistIdx(-1);
86	        setInput('');
87	
88	        if (cmd === 'help') {
89	            setShowSheet(true);
90	            return;
91	        }
92	        if (cmd === 'clear') {
93	            setLines([{ id: lineId++, text: 'Terminal cleared.', type: 'info' }]);
94	            return;
95	        }
96	
97	        if (wsRef.current?.readyState === WebSocket.OPEN) {
98	            wsRef.current.send(JSON.stringify({ command: cmd }));
99	        } else {
100	            // Fallback: HTTP terminal endpoint
101	            apiFetch('/api/terminal/run', {
102	                method: 'POST',
103	                headers: { 'Content-Type': 'application/json' },
104	                body: JSON.stringify({ command: cmd })
105	            })
106	            .then(r => r.json())
107	            .then(d => {
108	                const out = d.stdout || '';
109	                const err = d.stderr || d.error || '';
110	                if (out) setLines(prev => [...prev, { id: lineId++, text: String(out), type: 'out' }]);
111	                if (err) setLines(prev => [...prev, { id: lineId++, text: String(err), type: 'err' }]);
112	            })
113	            .catch(e => setLines(prev => [...prev, { id: lineId++, text: `Error: ${e.message}`, type: 'err' }]));
114	        }
115	    }, [input]);
116	
117	    const onKeyDown = useCallback((e: React.KeyboardEvent) => {
118	        if (e.key === 'Enter') { submit(); return; }
119	        if (e.key === 'ArrowUp') {
120	            const idx = Math.min(histIdx + 1, history.length - 1);
121	            setHistIdx(idx);
122	            setInput(history[idx] || '');
123	        }
124	        if (e.key === 'ArrowDown') {
125	            const idx = Math.max(histIdx - 1, -1);
126	            setHistIdx(idx);
127	            setInput(idx < 0 ? '' : history[idx] || '');
128	        }
129	    }, [submit, history, histIdx]);
130	
131	    return (
132	        <div style={{ display: 'flex', height: '100%', fontFamily: 'JetBrains Mono, monospace', fontSize: 12 }}>
133	            {/* Output pane */}
134	            <div style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
135	                <div style={{ flex: 1, overflowY: 'auto', padding: '8px 12px' }}>
136	                    {lines.map(l => (
137	                        <div key={l.id} style={{ lineHeight: 1.6, color: LINE_COLOR[l.type], whiteSpace: 'pre-wrap', wordBreak: 'break-all' }}>
138	                            {l.text}
139	                        </div>
140	                    ))}
141	                    <div ref={bottomRef}/>
142	                </div>
143	                <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '6px 12px', borderTop: '1px solid rgba(159,232,115,0.1)' }}>
144	                    <span style={{ color: 'var(--cyan-glow)', userSelect: 'none' }}>$</span>
145	                    <input
146	                        value={input}
147	                        onChange={e => setInput(e.target.value)}
148	                        onKeyDown={onKeyDown}
149	                        style={{
150	                            flex: 1, background: 'none', border: 'none', outline: 'none',
151	                            color: 'var(--silver-albedo)', fontFamily: 'inherit', fontSize: 12
152	                        }}
153	                        placeholder="command..."
154	                        autoFocus
155	                    />
156	                </div>
157	            </div>
158	
159	            {/* Cheatsheet sidebar */}
160	            {showSheet && (
161	                <div style={{ width: 260, borderLeft: '1px solid rgba(159,232,115,0.1)', overflowY: 'auto', padding: '8px 12px' }}>
162	                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 8 }}>
163	                        <span style={{ fontSize: 9, letterSpacing: '0.12em', color: 'var(--gold-solar)', textTransform: 'uppercase' }}>Cheatsheet</span>
164	                        <button onClick={() => setShowSheet(false)} style={{ background: 'none', border: 'none', color: 'var(--text-dim)', cursor: 'pointer', fontSize: 10 }}>×</button>
165	                    </div>
166	                    {CHEATSHEET.map(section => (
167	                        <div key={section.category} style={{ marginBottom: 12 }}>
168	                            <div style={{ fontSize: 9, color: 'var(--cyan-glow)', letterSpacing: '0.1em', marginBottom: 4, textTransform: 'uppercase', opacity: 0.7 }}>
169	                                {section.category}
170	                            </div>
171	                            {section.commands.map(c => (
172	                                <div key={c.cmd} style={{ marginBottom: 4, cursor: 'pointer' }}
173	                                    onClick={() => setInput(c.cmd.replace(/<[^>]+>/g, ''))}>
174	                                    <div style={{ color: 'var(--gold-solar)', fontSize: 10 }}>{c.cmd}</div>
175	                                    <div style={{ color: 'rgba(247,247,247,0.4)', fontSize: 10 }}>{c.desc}</div>
176	                                </div>
177	                            ))}
178	                        </div>
179	                    ))}
180	                </div>
181	            )}
182	        </div>
183	    );
184	}
185	
186	const LINE_COLOR: Record<TermLine['type'], string> = {
187	    cmd:  'var(--cyan-glow)',
188	    out:  'rgba(247,247,247,0.8)',
189	    err:  'var(--red-fusion)',
190	    info: 'rgba(247,247,247,0.35)'
191	};
