42	    DEFAULT_PORT,
43	    DEFAULT_PORT + 1,
44	    DEFAULT_PORT - 1,
45	    ...Array.from({ length: Math.max(0, MAX_PORT - DEFAULT_PORT - 1) }, (_, index) => DEFAULT_PORT + index + 2)
46	].filter((port, index, ports) => port > 0 && ports.indexOf(port) === index);
