83	
84	const trackedTimeouts = new Set<NodeJS.Timeout>();
85	const trackedIntervals = new Set<NodeJS.Timeout>();
86	
87	function trackTimeout(handle: NodeJS.Timeout) {
88	    trackedTimeouts.add(handle);
89	    return handle;
90	}
91	
92	function trackInterval(handle: NodeJS.Timeout) {
93	    trackedIntervals.add(handle);
94	    return handle;
95	}
96	
97	function clearTrackedTimers() {
98	    for (const timeout of trackedTimeouts) clearTimeout(timeout);
99	    for (const interval of trackedIntervals) clearInterval(interval);
100	    trackedTimeouts.clear();
101	    trackedIntervals.clear();
102	}
103	
104	function isRecoverableListenError(error: unknown): error is NodeJS.ErrnoException {
105	    return Boolean(
106	        error &&
107	        typeof error === 'object' &&
108	        'code' in error &&
109	        ['EADDRINUSE', 'EPERM', 'EACCES'].includes(String((error as NodeJS.ErrnoException).code))
110	    );
111	}
112	
113	function canBindPort(port: number): Promise<boolean> {
114	    return new Promise((resolve) => {
115	        const probe = net.createServer();
116	
117	        const cleanup = () => {
118	            probe.removeAllListeners('error');
119	            probe.removeAllListeners('listening');
120	        };
121	
122	        probe.once('error', () => {
123	            cleanup();
124	            resolve(false);
125	        });
126	
127	        probe.once('listening', () => {
128	            cleanup();
129	            probe.close(() => resolve(true));
130	        });
131	
132	        try {
133	            probe.listen(port, HOST);
134	        } catch {
135	            cleanup();
136	            resolve(false);
137	        }
138	    });
139	}
140	
141	function listenOnPort(port: number): Promise<void> {
142	    return new Promise((resolve, reject) => {
143	        const handleError = (error: NodeJS.ErrnoException) => {
144	            server.off('listening', handleListening);
145	            reject(error);
146	        };
147	
148	        const handleListening = () => {
149	            server.off('error', handleError);
150	            resolve();
151	        };
152	
153	        server.once('error', handleError);
154	        server.once('listening', handleListening);
155	
156	        try {
157	            server.listen(port, HOST);
158	        } catch (error) {
159	            server.off('error', handleError);
160	            server.off('listening', handleListening);
161	            reject(error);
162	        }
163	    });
164	}
