166	function isAllowedCorsOrigin(origin: string) {
167	    try {
168	        const parsed = new URL(origin);
169	        return LOOPBACK_HOSTS.has(parsed.hostname);
170	    } catch {
171	        return false;
172	    }
173	}
174	
175	const corsOptions: CorsOptions = {
176	    origin(origin, callback) {
177	        if (!origin || isAllowedCorsOrigin(origin)) {
178	            callback(null, true);
179	            return;
180	        }
181	
182	        callback(new Error('CORS_BLOCKED'));
183	    }
184	};
