205	async function buildHealthPayload() {
206	    const dbHealthy = checkDatabaseHealth();
207	    const obsidianState = obsidianRest.getStatus();
208	    const obsidianOnline = obsidianState.mode !== 'offline';
209	    const watcherStatus = vaultWatcherController?.getStatus() || {
