218	    return {
219	        healthy,
220	        status: healthy ? 'healthy' : 'degraded',
221	        timestamp: new Date().toISOString(),
222	        uptimeSeconds: Math.round(process.uptime()),
223	        services: {
224	            database: dbHealthy ? 'online' : 'offline',
225	            obsidian: obsidianOnline ? 'online' : 'offline',
226	            vaultWatcher: watcherStatus.running ? 'online' : 'offline',
227	            stabilityGuard: guardStatus.running ? 'online' : 'offline'
228	        },
229	        ingestion: ingestionStatus,
230	        watcher: watcherStatus,
231	        obsidian: obsidianRest.getStatus(),
232	        memory: {
