246	
247	async function buildReadinessPayload() {
248	    const dbHealthy = checkDatabaseHealth();
249	    const ingestionStatus = getVaultIngestionStatus();
250	    const initialIngestionSettled = Boolean(ingestionStatus.lastResult || ingestionStatus.lastError);
251	
252	    let reason = 'ready';
253	    if (shuttingDown) reason = 'shutting_down';
254	    else if (!dbHealthy) reason = 'database_unavailable';
255	    else if (!backgroundServicesStarted) reason = 'background_services_starting';
256	    else if (!initialIngestionSettled) reason = 'initial_ingestion_in_progress';
257	
258	    const ready = reason === 'ready';
259	
260	    return {
261	        ready,
262	        status: ready ? 'ready' : 'not_ready',
263	        reason,
264	        timestamp: new Date().toISOString(),
265	        authRuntimeReady: Boolean(getRuntimeApiKey()),
266	        ingestion: ingestionStatus
