270	const clamp = (value: number) => Math.min(100, Math.max(0, value));
271	
272	async function computeTelemetry() {
273	    const agents = getAllAgents(db);
274	    const activeCount = agents.filter((agent) => agent.status === 'ACTIVE' || agent.status === 'SYNCING').length;
275	    const { total: knowledgeTotal } = getIngestionStats(db);
276	    const metrics = await getTokenMetrics();
277	    const tokenLoad = metrics.currentSession ? (metrics.currentSession.tokens / 200000) * 100 : 20;
278	
279	    const snapshot = {
280	        neural_density: clamp(tokenLoad + (Math.random() * 5)),
281	        swarm_sync: clamp(activeCount * 5 + 50 + (Math.random() * 15)),
282	        ingestion_pressure: clamp((knowledgeTotal / 1000) * 100 * (0.8 + Math.random() * 0.4)),
283	        seal_stability: clamp(98 + Math.random() * 2),
284	        logic_throughput: clamp(75 + Math.random() * 25),
285	        active_agent_count: activeCount
286	    };
287	
288	    recordTelemetry(db, snapshot);
289	    return { snapshot, metrics };
