342	async function checkIntegrations() {
343	    if (shuttingDown) return;
344	
345	    try {
346	        const obsidianState = obsidianRest.getStatus();
347	        const isPingOk = obsidianState.mode === 'rest'
348	            ? await obsidianRest.ping()
349	            : true;
350	        const obsidianAvailable = isPingOk || obsidianState.mode !== 'offline';
351	        obsidianFailCount = obsidianAvailable ? 0 : obsidianFailCount + 1;
352	
353	        const obsidianStatus = obsidianAvailable ? 'CONNECTED' : 'OFFLINE';
354	        const forgeStatus = await neuralForge.ping();
355	        const isForgeOnline = forgeStatus.local || forgeStatus.cloud || forgeStatus.anthropic || forgeStatus.google || forgeStatus.openai;
356	
357	        const integrations = [
358	            { name: 'OBSIDIAN', status: obsidianStatus },
359	            { name: 'NEURAL_FORGE', status: isForgeOnline ? 'CONNECTED' : 'OFFLINE' },
360	            { name: 'GITNEXUS_MCP', status: 'CONNECTED' }
361	        ];
362	
363	        for (const integration of integrations) {
364	            const exists = db.prepare('SELECT 1 FROM integrations WHERE name = ?').get(integration.name);
365	            if (exists) {
366	                db.prepare("UPDATE integrations SET status = ?, last_sync = datetime('now') WHERE name = ?")
367	                    .run(integration.status, integration.name);
368	            } else {
369	                db.prepare("INSERT INTO integrations (name, status, last_sync) VALUES (?, ?, datetime('now'))")
370	                    .run(integration.name, integration.status);
371	            }
372	        }
373	
374	        if (obsidianStatus === 'CONNECTED' && obsidianFailCount > 0) {
375	            console.warn(`⬡ OBSIDIAN_PULSE :: STABILIZING (${obsidianFailCount}/${FAIL_THRESHOLD})`);
376	        } else if (obsidianStatus === 'OFFLINE') {
377	            console.error('⬡ OBSIDIAN_PULSE :: CRITICAL_OFFLINE');
378	        }
379	    } catch (error) {
380	        console.error('⬡ INTEGRATION_CHECK_ERROR:', error);
381	    }
382	}
