464	function attachWebSocketServer(socketServer: WebSocketServer) {
465	    socketServer.on('connection', async (ws, req) => {
466	        if (shuttingDown) {
467	            ws.close(1012, 'Server shutting down');
468	            return;
469	        }
470	
471	        // Shell bridge — handles terminal command execution
472	        if ((req as any).url === '/ws/shell') {
473	            ws.on('message', (raw: Buffer) => {
474	                try {
475	                    const { command } = JSON.parse(raw.toString());
476	                    if (typeof command !== 'string' || !command.trim()) return;
477	                    const child = spawn(command, [], { cwd: SystemConfig.ROOT, shell: true, env: process.env });
478	                    child.stdout.on('data', (d: Buffer) => ws.send(JSON.stringify({ type: 'stdout', data: d.toString() })));
479	                    child.stderr.on('data', (d: Buffer) => ws.send(JSON.stringify({ type: 'stderr', data: d.toString() })));
480	                    child.on('close', (code: number | null) => ws.send(JSON.stringify({ type: 'exit', code })));
481	                    child.on('error', (err: Error) => ws.send(JSON.stringify({ type: 'stderr', data: err.message })));
482	                } catch (_) {}
483	            });
484	            return;
485	        }
486	
487	        console.log('⬡ NEW_SEEKER_CONNECTED');
488	        logEvent(db, 'SYSTEM', 'WEBSOCKET', 'New seeker connected to the Command Center', 'INFO');
489	        ws.send(JSON.stringify(await buildStatusPayload()));
490	    });
491	
492	    EventBus.GlobalBus.on('CONCLAVE_EVENT', (artifact) => {
493	        if (shuttingDown) return;
494	
495	        socketServer.clients.forEach((client) => {
496	            if (client.readyState === 1) {
497	                client.send(JSON.stringify({
498	                    type: 'CONCLAVE_THOUGHT',
499	                    artifact
500	                }));
501	            }
502	        });
503	    });
504	}
