547	async function gracefulShutdown(signal: string) {
548	    if (shuttingDown) return;
549	    shuttingDown = true;
550	
551	    bootLog(`⬡ SHUTDOWN_SIGNAL_RECEIVED :: ${signal}`);
552	    clearTrackedTimers();
553	    guard.stop();
554	
555	    try {
556	        await vaultWatcherController?.close();
557	        bootLog('⬡ VAULT_WATCHER_STOPPED');
558	    } catch (error: any) {
559	        bootLog(`⬡ VAULT_WATCHER_STOP_ERROR: ${error.message}`);
560	    }
561	
562	    wss?.clients.forEach((client) => {
563	        if (client.readyState === 1) {
564	            client.close(1001, 'Server shutting down');
565	        }
566	    });
567	
568	    const forcedExit = setTimeout(() => {
569	        bootLog('⬡ FORCED_EXIT :: Timed out while shutting down');
570	        process.exit(1);
571	    }, 5000);
572	
573	    try {
574	        if (wss) {
575	            await new Promise<void>((resolve) => wss!.close(() => resolve()));
576	        }
577	        await new Promise<void>((resolve) => server.close(() => resolve()));
578	    } finally {
579	        clearTimeout(forcedExit);
580	    }
581	
582	    try {
583	        db.close();
584	        bootLog('⬡ DATABASE_CLOSED');
585	    } catch (error: any) {
586	        bootLog(`⬡ DATABASE_CLOSE_ERROR: ${error.message}`);
587	    }
588	
589	    process.exit(0);
590	}
