600	async function startServer() {
601	    for (let index = 0; index < PORT_CANDIDATES.length; index += 1) {
602	        const port = PORT_CANDIDATES[index];
603	        currentPort = port;
604	        const nextPort = PORT_CANDIDATES[index + 1];
605	
606	        const bindable = await canBindPort(port);
607	        if (!bindable) {
608	            if (nextPort) {
609	                bootLog(`⬡ PORT_COLLISION :: ${port} unavailable. Trying ${nextPort}...`);
610	                continue;
611	            }
612	            break;
613	        }
614	
615	        try {
616	            await listenOnPort(port);
617	            wss = new WebSocketServer({ server });
618	            attachWebSocketServer(wss);
619	
620	            server.on('error', (error: any) => {
621	                bootLog(`⬡ SERVER_ERROR: ${error.message}`);
622	            });
623	
624	            bootLog(`⬡ NUDIMMUD_BACKEND_ONLINE :: ${HOST}:${currentPort}`);
625	            logEvent(db, 'SYSTEM', 'SERVER', `Backend server started on ${HOST}:${currentPort}`, 'INFO');
626	            return;
627	        } catch (error) {
628	            if (isRecoverableListenError(error) && nextPort) {
629	                bootLog(`⬡ PORT_COLLISION :: ${port} failed during bind (${error.code}). Trying ${nextPort}...`);
630	                continue;
631	            }
632	
633	            throw error;
634	        }
635	    }
636	
637	    throw new Error(`Port exhaustion. No ports available around ${DEFAULT_PORT}.`);
638	}
639	
